(1994629, 274168, 31133, '<td valign="top">This is my favorite so far (of about 50 images viewed)! It''s got warmth, humor, and good technical aspects: framing, color, and light. This just makes me smile a lot.</td>', 'This is my favorite so far (of about 50 images viewed)! It''s got warmth, humor, and good technical aspects: framing, color, and light. This just makes me smile a lot.', '2006-01-02 09:27:19.000000', NULL, 1),
(1994630, 274699, 47852, '<td valign="top">Adorable expression on the boys face, and I love the everyday feel of mom''s clothing and hair.</td>', 'Adorable expression on the boys face, and I love the everyday feel of mom''s clothing and hair.', '2006-01-02 09:27:29.000000', NULL, 1),
(1994631, 274923, 39106, '<td valign="top">LOL, very funny, this made me laugh.</td>', 'LOL, very funny, this made me laugh.', '2006-01-02 09:28:23.000000', NULL, 1),
