(1997731, 274676, 28299, '<td valign="top">Really adorable; like the sepia tones. 8</td>', 'Really adorable; like the sepia tones. 8', '2006-01-03 07:06:38.000000', NULL, 1),
(1997732, 274846, 48228, '<td valign="top">Very well captured and I like this image..........</td>', 'Very well captured and I like this image..........', '2006-01-03 07:07:37.000000', NULL, 1),
(1997735, 273908, 48228, '<td valign="top">Age has no boundries, and the love in this image is so strong. Her eyes sparkle , each and every wrinkle is etched with love, a very moving and powerful image here, and another one that so deserves a ribbon...... So, so good.</td>', 'Age has no boundries, and the love in this image is so strong. Her eyes sparkle , each and every wrinkle is etched with love, a very moving and powerful image here, and another one that so deserves a ribbon...... So, so good.', '2006-01-03 07:11:59.000000', NULL, 1),
(1997736, 274986, 48228, '<td valign="top">So soft, so pure etched witth love...........</td>', 'So soft, so pure etched witth love...........', '2006-01-03 07:12:57.000000', NULL, 1),
(1997738, 273942, 37544, '<td valign="top">I am sorry, but I do not see the relationship to the theme with this photo. "Mother" can represent many ideas and views but I cannot see how this photo represents "Mother".</td>', 'I am sorry, but I do not see the relationship to the theme with this photo. "Mother" can represent many ideas and views but I cannot see how this photo represents "Mother".', '2006-01-03 07:13:13.000000', NULL, 1),
