INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2016368, 274937, 30364, '<td valign="top">This is a nice idea, but there''s something odd about the mother''s gaze; it''s clearly directed somewhere back behind the boy''s ear, and she looks concerned rather than maternal, as if she''s checking him for head lice.  From a technical point of view the highlights are perhaps blown out a bit, but that''s less of a bother for me than is the mother''s detached expression, which rather undermines the intended meaning of the photograph.</td>', 'This is a nice idea, but there''s something odd about the mother''s gaze; it''s clearly directed somewhere back behind the boy''s ear, and she looks concerned rather than maternal, as if she''s checking him for head lice.  From a technical point of view the highlights are perhaps blown out a bit, but that''s less of a bother for me than is the mother''s detached expression, which rather undermines the intended meaning of the photograph.', '2006-01-08 22:48:38.000000', NULL, 1),
